INSERT OR IGNORE INTO dashboard_bookings (id, property_id, property_name, property_code, guest, platform, status, checkin, checkout, nights, amount, extra_bed_quantity, extra_bed_price, cleaning_fee, platform_fee_pct, note, cancellation_reason, refund_amount, income_entry_id, created_by, created_at, updated_at) VALUES ('BKE20260926-9001', 'CSB', '', 'CSB', '(tanpa nama)', 'Direct', 'Checked-out', '2026-09-26', '2026-09-27', 1, 4841851, 0, 0, 0, 0, 'Import Excel 2026 - baris tanpa nama tamu', '', 0, 'booking-income-BKE20260926-9001', 'import-excel-2026-tambahan', datetime('now'), datetime('now'));
UPDATE dashboard_bookings SET property_id = COALESCE(NULLIF(TRIM((SELECT dashboard_id FROM properties WHERE property_code = dashboard_bookings.property_code)), ''), (SELECT id FROM properties WHERE property_code = dashboard_bookings.property_code), 'BELUM-' || property_code), property_name = COALESCE((SELECT name FROM properties WHERE property_code = dashboard_bookings.property_code), 'Properti ' || property_code || ' - kode perlu diperiksa'), note = CASE WHEN (SELECT COUNT(*) FROM properties WHERE property_code = dashboard_bookings.property_code) = 0 AND note NOT LIKE '%KODE PERLU DIPERIKSA%' THEN note || ' - KODE PERLU DIPERIKSA' ELSE note END WHERE created_by = 'import-excel-2026-tambahan';
INSERT OR IGNORE INTO finance_entries (id, kind, category_id, category_name, property_id, property_name, entry_date, amount, description, payee, recurrence, created_by, created_at)
SELECT b.income_entry_id, 'income', 'income-booking', 'Booking', b.property_id, b.property_name, b.checkin, b.amount, 'Booking ' || b.id || ' - ' || b.guest, b.platform, 'once', b.created_by, b.created_at
FROM dashboard_bookings b WHERE b.created_by = 'import-excel-2026-tambahan';
